(() => {
  try {
    const body = document.body.innerText;
    const lines = body.split('\n').map(l => l.trim()).filter(l => l.length > 0);
    const keywords = ['等级', '好感', '技能', '田地', '田块', '事件', '经验', '天数', '季节', '金币', '资金', '体力', '健康', '水稻', '红薯', '钓鱼', '养殖', 'NPC', '村民'];
    const filtered = lines.filter(l => keywords.some(k => l.includes(k)));
    return JSON.stringify({totalLines: lines.length, matched: filtered.length, data: filtered.slice(0, 50)});
  } catch(e) {
    return JSON.stringify({error: e.message});
  }
})()
